#include <cstdio>
#include <cstdlib>
#include <cstdint>
#include <cstring>
using namespace std;
int G[12][24],gray[8],target[24],message[12],chosen[12];uint64_t leaves=0,conflicts=0;bool found=false;int witness_distance=0;
void visit(int depth,int budget){if(depth==12){leaves++;int used=0;for(int j=12;j<24;j++){int z=0;for(int i=0;i<12;i++)z+=message[i]*G[i][j];int d=__builtin_popcount((unsigned)(gray[z&7]^target[j]));if((d&1)!=1)abort();used+=(d-1)/2;if(used>budget)return;}conflicts++;if(!found){witness_distance=20+2*(1-budget+used);for(int i=0;i<12;i++)chosen[i]=message[i];}found=true;return;}int partial=0;for(int i=0;i<depth;i++)partial+=message[i]*G[i][depth];for(int z=0;z<8;z++){int d=__builtin_popcount((unsigned)(gray[z]^target[depth]));int extra;if(depth<4){if(__builtin_popcount((unsigned)gray[z])!=2)continue;if(d&1)abort();extra=d/2;}else{if(!(d&1))abort();extra=(d-1)/2;}if(extra>budget)continue;message[depth]=(7*(z-partial))&7;visit(depth+1,budget-extra);}}
int main(int argc,char**argv){if(argc<2)return 2;if(strlen(argv[1])!=24)return 3;for(int j=0;j<24;j++){char c=argv[1][j];if(c>='A'&&c<='F')c+=('a'-'A');target[j]=(c>='0'&&c<='9')?c-'0':10+c-'a';if(target[j]<0||target[j]>15)return 3;if(j<4&&__builtin_popcount((unsigned)target[j])!=2)return 3;if(j>=4&&__builtin_popcount((unsigned)target[j])%2!=1)return 3;}int g[]={7,1,4,4,2,7,3,3,4,7,2,1};for(int i=0;i<12;i++){for(int j=0;j<12;j++)G[i][i+j]=g[j];G[i][23]=3;}for(int z=0;z<8;z++){gray[z]=0;for(int x=0;x<2;x++)for(int y=0;y<2;y++)gray[z]|=(((z>>2&1)^((z&1)*x)^(((z>>1&1)*y)))<<(2*x+y));}visit(0,1);if(found){printf("WITNESS B ");for(int x:chosen)printf("%d",x);printf(" distance %d leaves %llu CONFLICTS %llu\n",witness_distance,(unsigned long long)leaves,(unsigned long long)conflicts);}else{if(leaves!=1638400ull){fprintf(stderr,"unexpected leaf count %llu\n",(unsigned long long)leaves);return 4;}printf("EXACT_HOLE leaves %llu\n",(unsigned long long)leaves);}return 0;}
